const{chromium}=require('C:/Users/GuillaumePelletier/Documents/GitHub/Gaume/spacexr-atmosphere/node_modules/playwright');
(async()=>{const b=await chromium.launch({channel:'chrome',headless:true,args:['--enable-unsafe-webgpu','--use-angle=d3d11','--ignore-gpu-blocklist']});try{const p=await b.newPage({viewport:{width:2560,height:1440}});await p.addInitScript(()=>{const raf=requestAnimationFrame;window.requestAnimationFrame=cb=>raf(t=>{if(!window.stopProbeFrame)cb(t);});const req=GPUAdapter.prototype.requestDevice;GPUAdapter.prototype.requestDevice=async function(...args){const d=await req.apply(this,args);const create=d.createCommandEncoder.bind(d);d.createCommandEncoder=desc=>{const e=create(desc);for(const method of['beginComputePass','beginRenderPass']){const begin=e[method].bind(e);e[method]=desc=>{if(window.profileQuery){const i=window.profileNames.length*2;window.profileNames.push(desc?.label||(method==='beginRenderPass'?'scene/render':'compute'));desc={...desc,timestampWrites:{querySet:window.profileQuery,beginningOfPassWriteIndex:i,endOfPassWriteIndex:i+1}};}return begin(desc);};}return e;};return d;};});await p.goto('http://127.0.0.1:5189/atmosphere.html?sunset=1&sse=20');await p.waitForFunction(()=>window.earthDemo?.earth.atmosphereReady,{},{timeout:60000});await p.waitForTimeout(6000);
console.log(await p.evaluate(async()=>{window.stopProbeFrame=true;await new Promise(r=>setTimeout(r,100));const earth=window.earthDemo.earth,engine=earth.camera.getScene().getEngine(),scene=earth.camera.getScene(),d=engine._device;await d.queue.onSubmittedWorkDone();if(!d.features.has('timestamp-query'))throw Error('No GPU timestamp support');const reports=[];for(const angle of[0.1,0.5,0.1]){earth.camera.yaw+=angle;const query=d.createQuerySet({type:'timestamp',count:256}),buffer=d.createBuffer({size:2048,usage:GPUBufferUsage.QUERY_RESOLVE|GPUBufferUsage.COPY_SRC}),read=d.createBuffer({size:2048,usage:GPUBufferUsage.COPY_DST|GPUBufferUsage.MAP_READ});window.profileQuery=query;window.profileNames=[];const start=performance.now();await earth.update();const update=performance.now()-start;engine.beginFrame();scene.render(false);engine.endFrame();window.profileQuery=undefined;const count=window.profileNames.length*2;const encoder=d.createCommandEncoder();encoder.resolveQuerySet(query,0,count,buffer,0);encoder.copyBufferToBuffer(buffer,0,read,0,count*8);d.queue.submit([encoder.finish()]);await read.mapAsync(GPUMapMode.READ);const values=new BigUint64Array(read.getMappedRange()),stages={};for(let i=0;i<window.profileNames.length;i++){const label=window.profileNames[i];stages[label]=(stages[label]??0)+Number(values[2*i+1]-values[2*i])/1e6;}reports.push({angle,update,total:performance.now()-start,stages});read.unmap();query.destroy();read.destroy();buffer.destroy();}return reports;}));await p.evaluate(()=>window.earthDemo.dispose());}finally{await b.close();}})().catch(e=>{console.error(e);process.exitCode=1;});
